/// <summary>
/// The <c>LedgerJournalCheckPost</c> class validates and posts ledger journals.
/// </summary>
[ExtensionOf(classStr(LedgerJournalCheckPost))]
final class AVALedgerJournalCheckPostCls_Extension
{
    private     boolean     bec_use_autoSwapNumberSeq;
    private     RefRecId    bec_use_NumberSequenceId;

}

Method.Source:
/// <summary>
/// Gets a <c>NumberSeq</c> object.
/// </summary>
/// <param name = "_numberSequenceId">
/// A number sequence id.
/// </param>
/// <returns>
/// A <c>NumberSeq</c> object.
/// </returns>
protected final NumberSeq getNumberSeq(RefRecId _numberSequenceId)
{
    RefRecId numberSequenceId = _numberSequenceId;

    if (bec_use_autoSwapNumberSeq && bec_use_NumberSequenceId)
    {
        numberSequenceId = bec_use_NumberSequenceId;
    }

    return next getNumberSeq(numberSequenceId);
}

