/// <summary>
///    Posts the current instance of a journal.
/// </summary>
/// <returns>
///    true if the journal was posted; otherwise, false.
/// </returns>
/// <exception cref="M:Exception::Error">
///    The journal is not approved or balanced.
/// </exception>
/// <exception cref="M:Exception::Error">
///    The account or amount is not set.
/// </exception>
/// <exception cref="M:Exception::Error">
///    The voucher number is not set for the ledger journal line.
/// </exception>
protected container postJournal()
{
    container con = next postJournal();

    // BEC/KNMAR/T11780/2019-07-18
    // Update of ledger import table data for successfully posted ledger
    //BEC_MsqlLedgerImportTable::markAsPostedByJournal(ledgerJournalTable);

    if (conPeek(con, 1))
    {
        if (ledgerJournalTable.AVAAllocationRefRecId)
        {
            ttsbegin;
            //LedgerJournalTable allocLedgerJournalTable_bec = LedgerJournalTable::findRecId(ledgerJournalTable.AVAAllocationRefRecId, true);
            ledgerJournalTable allocLedgerJournalTable_bec = ledgerJournalTable::findByRecId(ledgerJournalTable.AVAAllocationRefRecId, true);
            if (allocLedgerJournalTable_bec)
            {
                allocLedgerJournalTable_bec.AVAPostedWithDifLayer = NoYes::Yes;
                allocLedgerJournalTable_bec.doUpdate();
            }
            ttscommit;
        }
    }

    return con;
}

/// <summary>
/// Extension of the method validate
/// </summary>
/// <param name = "_calledFrom">Identifies the object from which this method is called. Default value is null.</param>
/// <returns>true if the journal is valid for posting; otherwise, false.</returns>
public boolean validate(Object _calledFrom)
{
    boolean isValid = next validate(_calledFrom);

    if (ledgerJournalTable.AVAPostedWithDifLayer || ledgerJournalTable.AVACopiedWithDifLayer)
    {
        isValid = false;
    }

    return isValid;
}
